// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  CheckIcon,
  DownloadIcon,
  FileArchiveIcon,
  FilterIcon,
  RefreshCwIcon,
  SearchIcon,
} from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  exampleName,
  ITEMS,
  MIN_WIDTH,
  PAGE_URL,
  PHOTOS,
  PICKED,
  SKIP,
  SLIDER_MAX,
  TEMPLATE,
  VISIBLE,
  ZIP,
  type Item,
} from './script'

const RING = '0 0 0 2px #f5f5f7'
const FLYERS = 3

const build: Build = ({ tl, q, qa, step, final, move, click, count, fly, wait, cursorOut }) => {
  let total = ITEMS.length
  const setCount = (to: number) => {
    count('download-count', to, { from: total, at: '<', duration: 0.3 })
    total = to
  }

  step(0)
  tl.to(q('skeleton'), { opacity: 0, duration: 0.3 }, 0.6)
  tl.fromTo(
    qa('cell'),
    { opacity: 0, scale: 0.85 },
    {
      opacity: 1,
      scale: 1,
      duration: 0.3,
      stagger: 0.03,
      ease: 'back.out(2)',
      immediateRender: false,
    },
    '<',
  )
  count('visible-count', ITEMS.length, { at: '<', duration: 0.6 })

  step(1, '+=0.5')
  move('filters')
  click('filters')
  tl.fromTo(
    q('popover'),
    { opacity: 0, y: -4 },
    { opacity: 1, y: 0, duration: 0.2, immediateRender: false },
    '<',
  )
  move('slider', { ax: 0, at: '+=0.1' })
  click('slider')
  move('slider', { ax: MIN_WIDTH / SLIDER_MAX, duration: 0.6 })
  tl.to(
    q('slider-fill'),
    { width: `${(MIN_WIDTH / SLIDER_MAX) * 100}%`, duration: 0.6, ease: 'power3.inOut' },
    '<',
  )
  tl.to(
    q('slider-knob'),
    { left: `${(MIN_WIDTH / SLIDER_MAX) * 100}%`, duration: 0.6, ease: 'power3.inOut' },
    '<',
  )
  tl.to(qa('icon-cell'), { opacity: 0, scale: 0.6, duration: 0.3, stagger: 0.05 }, '>-0.2')
  count('visible-count', VISIBLE, { from: ITEMS.length, at: '<', duration: 0.3 })
  setCount(VISIBLE)
  tl.fromTo(
    q('filter-badge'),
    { scale: 0 },
    { scale: 1, duration: 0.25, ease: 'back.out(3)', immediateRender: false },
    '<',
  )
  move('filters', { at: '+=0.2' })
  click('filters')
  tl.to(q('popover'), { opacity: 0, duration: 0.15 }, '<')

  step(2, '+=0.4')
  SKIP.forEach((index) => {
    move(`cell-${index}`, { ax: 0.5, ay: 0.5 })
    click(`cell-${index}`)
    tl.to(q(`cell-${index}`), { boxShadow: '0 0 0 0px #f5f5f7', duration: 0.15 }, '<')
    tl.to(q(`check-${index}`), { backgroundColor: 'rgba(0,0,0,0.35)', duration: 0.15 }, '<')
    tl.to(q(`tick-${index}`), { opacity: 0, duration: 0.1 }, '<')
    tl.to(q(`img-${index}`), { opacity: 0.45, duration: 0.15 }, '<')
    setCount(total - 1)
  })
  tl.set(q('example'), { text: `Example: ${exampleName(PICKED[0], 1)}` }, '<')

  step(3, '+=0.4')
  move('download')
  click('download')
  tl.fromTo(
    q('menu'),
    { opacity: 0, y: 4 },
    { opacity: 1, y: 0, duration: 0.18, immediateRender: false },
    '<',
  )
  move('mode-zip', { ax: 0.4 })
  click('mode-zip')
  tl.to(q('menu'), { opacity: 0, duration: 0.15 }, '<0.1')
  tl.to(q('example'), { opacity: 0, duration: 0.15 }, '<')
  tl.fromTo(
    q('progress'),
    { opacity: 0 },
    { opacity: 1, duration: 0.2, immediateRender: false },
    '<',
  )
  count('done', PICKED.length, { at: '<', duration: 1.4, ease: 'none' })
  tl.to(q('progress-fill'), { width: '100%', duration: 1.4, ease: 'none' }, '<')
  const flyAt = tl.duration() - 1.3
  for (let index = 0; index < FLYERS; index++) {
    const source = PHOTOS.indexOf(PICKED[index])
    fly(`flyer-${index}`, `cell-${source}`, 'zip', {
      at: flyAt + index * 0.25,
      duration: 0.7,
      scale: 0.4,
      lift: 50,
    })
    tl.to(q(`flyer-${index}`), { opacity: 0, duration: 0.1 }, '>')
  }
  tl.fromTo(
    q('zip'),
    { opacity: 0, y: -8 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'power3.out', immediateRender: false },
    flyAt,
  )
  tl.fromTo(
    q('zip'),
    { scale: 1.08 },
    { scale: 1, duration: 0.3, ease: 'back.out(3)', immediateRender: false },
    flyAt + 1,
  )
  cursorOut('+=0.5')
  final()
  wait(1.2)

  tl.set([q('popover'), q('menu'), q('progress'), q('zip'), ...qa('flyer')], { opacity: 0 }, 0)
  tl.set(q('filter-badge'), { scale: 0 }, 0)
}

function Thumb({ item }: { item: Item }) {
  const icon = item.width < MIN_WIDTH
  return (
    <span
      className={icon ? 'mx-auto block rounded-full' : 'block size-full'}
      style={{
        background: `linear-gradient(135deg, ${item.from}, ${item.to})`,
        ...(icon
          ? { width: Math.max(4, item.width / 2), height: Math.max(4, item.width / 2) }
          : {}),
      }}
    />
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col">
      <DockHeader />
      <div className="relative flex min-h-0 flex-1 flex-col gap-1.5 p-2">
        <div className="flex items-center gap-1">
          <span className="flex h-5 min-w-0 flex-1 items-center gap-1 rounded-md border border-line-strong px-1.5 text-[8.5px] text-muted">
            <SearchIcon className="size-2.5" /> Filter by URL…
          </span>
          <span className="flex h-5 items-center gap-1 rounded-md border border-line-strong px-1.5 text-[8.5px] text-ink-soft">
            <RefreshCwIcon className="size-2.5" /> Rescan
          </span>
        </div>
        <div className="flex items-center gap-1 text-[8.5px]">
          <span
            data-d="visible-count"
            className="rounded-md bg-white/10 px-1.5 py-0.5 font-semibold text-ink"
          >
            0
          </span>
          <span
            data-d="filters"
            className="flex items-center gap-1 rounded-md border border-line-strong px-1.5 py-0.5 text-ink-soft"
          >
            <FilterIcon className="size-2.5" /> Filters
            <span
              data-d="filter-badge"
              className="rounded bg-ink px-1 text-[7.5px] font-bold text-canvas"
            >
              1
            </span>
          </span>
          <span className="px-1 text-ink-soft">All</span>
          <span className="px-1 text-ink-soft">None</span>
          <span className="px-1 text-ink-soft">Invert</span>
        </div>
        <div className="relative">
          <div data-d="skeleton" className="absolute inset-0 grid grid-cols-4 gap-1">
            {ITEMS.map((item) => (
              <span
                key={item.name}
                className="aspect-square animate-pulse rounded-md bg-white/10"
              />
            ))}
          </div>
          <div className="grid grid-cols-4 gap-1">
            {ITEMS.map((item, index) => {
              const icon = index >= PHOTOS.length
              return (
                <span
                  key={item.name}
                  data-d={`cell cell-${index}${icon ? ' icon-cell' : ''}`}
                  className="relative flex aspect-square items-center overflow-hidden rounded-md border border-line bg-[#26262c]"
                  style={{ boxShadow: RING }}
                >
                  <span data-d={`img-${index}`} className="block size-full content-center">
                    <Thumb item={item} />
                  </span>
                  <span
                    data-d={`check-${index}`}
                    className="absolute left-0.5 top-0.5 flex size-2.5 items-center justify-center rounded-sm bg-ink"
                  >
                    <CheckIcon
                      data-d={`tick-${index}`}
                      className="size-2 text-canvas"
                      strokeWidth={4}
                    />
                  </span>
                  <span className="absolute bottom-0.5 right-0.5 rounded bg-black/60 px-0.5 text-[6.5px] text-white">
                    {item.width}×{item.height}
                  </span>
                </span>
              )
            })}
          </div>
          <div
            data-d="popover"
            className="absolute left-6 top-0 z-10 w-[176px] space-y-1.5 rounded-lg border border-line-strong bg-[#17171c] p-2 opacity-0 shadow-2xl"
          >
            <p className="text-[8.5px] font-medium text-ink">Min width (px)</p>
            <span data-d="slider" className="relative block h-1 rounded-full bg-white/15">
              <span data-d="slider-fill" className="block h-full w-0 rounded-full bg-ink" />
              <span
                data-d="slider-knob"
                className="absolute top-1/2 -ml-1 -mt-1 size-2 rounded-full border border-ink bg-canvas"
                style={{ left: 0 }}
              />
            </span>
            <p className="text-[8.5px] font-medium text-ink">Min height (px)</p>
            <span className="relative block h-1 rounded-full bg-white/15">
              <span className="absolute top-1/2 -ml-1 -mt-1 size-2 rounded-full border border-ink bg-canvas" />
            </span>
            <div className="flex flex-wrap gap-0.5">
              {['jpg', 'jpeg', 'png', 'webp', 'gif', 'svg', 'avif'].map((type) => (
                <span
                  key={type}
                  className="rounded border border-line-strong px-1 text-[7.5px] text-ink-soft"
                >
                  {type}
                </span>
              ))}
            </div>
          </div>
        </div>
        <div className="mt-auto space-y-1 border-t border-line pt-1.5">
          <span className="block rounded-md border border-line-strong px-1.5 py-0.5 font-mono text-[8.5px] text-ink">
            {TEMPLATE}
          </span>
          <div className="relative">
            <p data-d="example" className="truncate text-[8px] text-muted">
              Example: {exampleName(PHOTOS[0], 1)}
            </p>
            <div data-d="progress" className="absolute inset-x-0 top-0 opacity-0">
              <p className="text-[8px] text-ink-soft">
                Downloading… <span data-d="done">0</span> / {PICKED.length} (0 failed)
              </p>
              <span className="mt-0.5 block h-1 rounded-full bg-white/10">
                <span
                  data-d="progress-fill"
                  className="block h-full w-0 rounded-full bg-[#22c55e]"
                />
              </span>
            </div>
          </div>
          <div className="relative">
            <span
              data-d="download"
              className="flex h-6 items-center justify-center gap-1 rounded-md bg-ink text-[9.5px] font-semibold text-canvas"
            >
              <DownloadIcon className="size-3" /> Download{' '}
              <span data-d="download-count">{ITEMS.length}</span>
            </span>
            <div
              data-d="menu"
              className="absolute bottom-full right-0 mb-1 w-[110px] rounded-md border border-line-strong bg-[#17171c] py-0.5 text-[8.5px] text-ink-soft opacity-0 shadow-xl"
            >
              <span className="block px-2 py-1">Separate files</span>
              <span data-d="mode-zip" className="block px-2 py-1 text-ink">
                Single ZIP
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Image Downloader scanning ${ITEMS.length} images, filtering out icons under ${MIN_WIDTH} px, deselecting two and saving the rest as one ZIP`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url={PAGE_URL} panel={<Panel />} panelWidth={232}>
        <div className="relative h-full bg-white p-3 text-[#0f172a]">
          <div className="mb-2 flex items-center gap-1.5">
            <span className="size-4 rounded-full" style={{ background: '#38bdf8' }} />
            <span className="text-[10px] font-semibold">Autumn moodboard</span>
            <span className="ml-auto size-4 rounded-full" style={{ background: '#f472b6' }} />
          </div>
          <div className="columns-3 gap-1.5">
            {PHOTOS.map((item) => (
              <span
                key={item.name}
                className="mb-1.5 block rounded-md"
                style={{
                  aspectRatio: `${item.width} / ${item.height}`,
                  background: `linear-gradient(135deg, ${item.from}, ${item.to})`,
                }}
              />
            ))}
          </div>
          <div
            data-d="zip"
            className="absolute right-2 top-2 flex items-center gap-1.5 rounded-lg border border-black/10 bg-white px-2 py-1.5 opacity-0 shadow-lg"
          >
            <FileArchiveIcon className="size-4 text-[#f59e0b]" />
            <span>
              <span className="block text-[8.5px] font-semibold">{ZIP}</span>
              <span className="block text-[8px] text-[#64748b]">{PICKED.length} images</span>
            </span>
          </div>
        </div>
      </BrowserChrome>
      {PICKED.slice(0, FLYERS).map((item, index) => (
        <span
          key={item.name}
          data-d={`flyer flyer-${index}`}
          className="absolute left-0 top-0 z-20 size-12 rounded-md opacity-0 shadow-xl"
          style={{ background: `linear-gradient(135deg, ${item.from}, ${item.to})` }}
        />
      ))}
    </DemoStage>
  )
}
